package com.rpgate.service;
import com.rpgate.dto.MovementDtos; import com.rpgate.dto.PersonnelDtos; import com.rpgate.model.Category; import com.rpgate.repository.MovementRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.time.format.DateTimeFormatter; import java.time.format.DateTimeParseException; import java.util.*;
@Service public class MovementService { private final MovementRepository repo; private final PersonnelService personnel; public MovementService(MovementRepository repo,PersonnelService personnel){this.repo=repo;this.personnel=personnel;} @Transactional public MovementDtos.Response create(MovementDtos.Request x){validate(x);MovementDtos.PersonRef person=resolvePerson(x.person());long id=repo.insert(x,person);repo.detail(id,x.category(),x.details());return repo.get(id);} @Transactional public MovementDtos.Response update(long id,MovementDtos.Request x){validate(x);if(repo.get(id)==null)throw new IllegalArgumentException("Movement not found");MovementDtos.PersonRef person=resolvePerson(x.person());if(repo.update(id,x,person)==0)throw new IllegalArgumentException("Movement not found or already cancelled");return repo.get(id);} public List<MovementDtos.Response> list(MovementDtos.Filter f){return repo.list(f);} public MovementDtos.Response get(long id){var x=repo.get(id);if(x==null)throw new IllegalArgumentException("Movement not found");return x;} public void delete(long id){if(repo.delete(id)==0)throw new IllegalArgumentException("Movement not found");} public void deleteAll(){repo.deleteAll();} private void validate(MovementDtos.Request x){if(x.category()==null||x.movementAt()==null||x.movementAt().isBlank()||x.person()==null||x.person().name()==null||x.person().name().isBlank())throw new IllegalArgumentException("Category, movement time, and person name are required");parseTime(x.movementAt(),"movementAt");validateDetails(x.category(),x.details());} private MovementDtos.PersonRef resolvePerson(MovementDtos.PersonRef p){if(p.personnelId()!=null){var existing=personnel.getOrThrow(p.personnelId());return new MovementDtos.PersonRef(existing.personnelId(),existing.armyNo(),existing.cardNo(),existing.rank(),existing.name(),existing.mobileNo(),existing.unit());}var existing=personnel.findByArmyOrCard(p.armyNo(),p.cardNo());if(existing==null)existing=personnel.create(new PersonnelDtos.Request(p.armyNo(),p.cardNo(),p.rank(),p.name(),p.mobileNo(),p.unit()));return new MovementDtos.PersonRef(existing.personnelId(),p.armyNo(),p.cardNo(),p.rank(),p.name(),p.mobileNo(),p.unit());} private void parseTime(String value,String field){try{OffsetDateTime.parse(value,DateTimeFormatter.ISO_DATE_TIME);}catch(DateTimeParseException e){try{LocalDateTime.parse(value,DateTimeFormatter.ISO_DATE_TIME);}catch(DateTimeParseException x){throw new IllegalArgumentException(field+" must be an ISO date/time");}}} private void validateDetails(Category c,Map<String,String>d){if(d==null)d=Map.of();List<String> required=switch(c){case LEAVE->List.of("leave_type");case TD_POSTING->List.of("movement_subtype");case VEHICLE->List.of("vehicle_no","driver_name");case OUTPASS->List.of("time_out");case NIGHT_PASS->List.of("time_out");};for(String k:required)if(d.get(k)==null||d.get(k).isBlank())throw new IllegalArgumentException("Missing detail: "+k);for(String k:List.of("time_out","expected_return","return_time"))if(d.get(k)!=null&&!d.get(k).isBlank())parseTime(d.get(k),k);if(d.get("pass_no")!=null&&d.get("pass_no").trim().isEmpty())throw new IllegalArgumentException("pass_no cannot be blank");if(d.get("vehicle_no")!=null&&d.get("vehicle_no").trim().isEmpty())throw new IllegalArgumentException("vehicle_no cannot be blank");}}
